class Solution {
public:
    std::vector<std::vector<int>> buildMatrix(int k, std::vector<std::vector<int>>& rowConditions, std::vector<std::vector<int>>& colConditions) {
        auto topoSort = [&](const std::vector<std::vector<int>>& edges) {
            std::vector<std::vector<int>> adj(k + 1);
            std::vector<int> indeg(k + 1, 0);
            for (const auto& e : edges) {
                adj[e[0]].push_back(e[1]);
                indeg[e[1]]++;
            }
            std::queue<int> q;
            for (int i = 1; i <= k; i++) {
                if (indeg[i] == 0) q.push(i);
            }
            std::vector<int> order;
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                order.push_back(u);
                for (int v : adj[u]) {
                    if (--indeg[v] == 0) q.push(v);
                }
            }
            return (int)order.size() == k ? order : std::vector<int>();
        };

        auto rowOrder = topoSort(rowConditions);
        auto colOrder = topoSort(colConditions);
        if (rowOrder.empty() || colOrder.empty()) return {};

        std::vector<int> rowPos(k + 1), colPos(k + 1);
        for (int i = 0; i < k; i++) {
            rowPos[rowOrder[i]] = i;
            colPos[colOrder[i]] = i;
        }

        std::vector<std::vector<int>> res(k, std::vector<int>(k, 0));
        for (int num = 1; num <= k; num++) {
            res[rowPos[num]][colPos[num]] = num;
        }
        return res;
    }
};

class Solution {
    public int[][] buildMatrix(int k, int[][] rowConditions, int[][] colConditions) {
        int[] rowOrder = topoSort(k, rowConditions);
        int[] colOrder = topoSort(k, colConditions);
        if (rowOrder.length == 0 || colOrder.length == 0) return new int[0][0];

        int[] rowPos = new int[k + 1];
        int[] colPos = new int[k + 1];
        for (int i = 0; i < k; i++) {
            rowPos[rowOrder[i]] = i;
            colPos[colOrder[i]] = i;
        }

        int[][] res = new int[k][k];
        for (int num = 1; num <= k; num++) {
            res[rowPos[num]][colPos[num]] = num;
        }
        return res;
    }

    private int[] topoSort(int k, int[][] edges) {
        java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
        for (int i = 0; i <= k; i++) adj.add(new java.util.ArrayList<>());
        int[] indeg = new int[k + 1];
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            indeg[e[1]]++;
        }
        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        for (int i = 1; i <= k; i++) {
            if (indeg[i] == 0) q.offer(i);
        }
        int[] order = new int[k];
        int idx = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            order[idx++] = u;
            for (int v : adj.get(u)) {
                if (--indeg[v] == 0) q.offer(v);
            }
        }
        return idx == k ? order : new int[0];
    }
}

var buildMatrix = function(k, rowConditions, colConditions) {
    function topoSort(edges) {
        const adj = Array.from({ length: k + 1 }, () => []);
        const indeg = new Array(k + 1).fill(0);
        for (const [u, v] of edges) {
            adj[u].push(v);
            indeg[v]++;
        }
        const q = [];
        for (let i = 1; i <= k; i++) {
            if (indeg[i] === 0) q.push(i);
        }
        const order = [];
        while (q.length > 0) {
            const u = q.shift();
            order.push(u);
            for (const v of adj[u]) {
                indeg[v]--;
                if (indeg[v] === 0) q.push(v);
            }
        }
        return order.length === k ? order : [];
    }

    const rowOrder = topoSort(rowConditions);
    const colOrder = topoSort(colConditions);
    if (rowOrder.length === 0 || colOrder.length === 0) return [];

    const rowPos = new Array(k + 1);
    const colPos = new Array(k + 1);
    for (let i = 0; i < k; i++) {
        rowPos[rowOrder[i]] = i;
        colPos[colOrder[i]] = i;
    }

    const res = Array.from({ length: k }, () => new Array(k).fill(0));
    for (let num = 1; num <= k; num++) {
        res[rowPos[num]][colPos[num]] = num;
    }
    return res;
};
